bounded_host_request.command:
set -euo pipefail
cd "$HOME/Project/Gserver/projects/TGtumbler/GateApp-Bot"
python3 -B scripts/userbot_test_client.py health
python3 -B - <<'PY'
import json,subprocess
chat=-1003847210571
targets={621:("東北",1675),990:("甲信越",1673),991:("北陸",1671),992:("北関東",1668),993:("東京",1666),994:("南関東",1664),995:("東海",1662),996:("関西",1683),997:("中国",1681),998:("四国",1679),999:("九州",1677)}
ids=",".join(map(str,targets))
def db(sql):
 p=subprocess.run(["docker","exec","-i","deploy-postgres-1","sh","-c",'exec psql -X -q -U "$POSTGRES_USER" -d gaybbs -At -F "|" -v ON_ERROR_STOP=1 -f -'],input=sql,text=True,capture_output=True,timeout=25)
 if p.returncode:raise RuntimeError("DB_READ_FAILED")
 return p.stdout.strip().splitlines()
rows=db(f"SELECT message_thread_id,board_key,message_id,state FROM topic_board_posts WHERE chat_id={chat} AND message_thread_id IN ({ids}) ORDER BY message_thread_id;")
entries=db(f"SELECT message_thread_id,message_id,state,pinned FROM topic_dm_entry_pins WHERE chat_id={chat} AND message_thread_id IN ({ids}) ORDER BY message_thread_id;")
if entries!=[f"{tid}|{targets[tid][1]}|published|f" for tid in sorted(targets)]:raise RuntimeError("POSTING_LEDGER_MISMATCH")
boards={621:1387,990:1388,991:1389,992:1390,993:1391,994:1392,995:1393,996:1168,997:1169,998:1170,999:1171}
# Exact ledger evidence was read back; the Kansai known message is not republished or reconciled here.
expected=[f"{tid}|block:{targets[tid][0]}|{boards[tid]}|"+("needs_reconcile" if tid==996 else "published") for tid in sorted(targets)]
if rows!=expected:raise RuntimeError("BOARD_LEDGER_CHANGED")
if set(boards)!=set(targets) or len(set(boards.values()))!=len(targets) or set(boards.values())&{v[1] for v in targets.values()}:raise RuntimeError("BOARD_TARGET_MISMATCH")
tasks=[{"tid":tid,"board":boards[tid],"posting":targets[tid][1]} for tid in sorted(targets)]
node=r"""
const fs=require("node:fs"),https=require("node:https");
const tasks=__TASKS__;
const chat=-1003847210571;
const token=fs.readFileSync(process.env.BOT_TOKEN_FILE||"/run/secrets/bot_token","utf8").trim();
function api(method,data){
 return new Promise((resolve,reject)=>{
  const body=JSON.stringify(data);
  const req=https.request({hostname:"api.telegram.org",port:443,path:"/bot"+token+"/"+method,method:"POST",family:4,agent:false,headers:{"Content-Type":"application/json","Content-Length":Buffer.byteLength(body)}},res=>{
   let s="";res.setEncoding("utf8");res.on("data",x=>{if(s.length<200000)s+=x;});res.on("end",()=>{try{resolve(JSON.parse(s));}catch{reject(Error("API_RESPONSE_INVALID"));}});
  });
  const timer=setTimeout(()=>req.destroy(Error("TIMEOUT")),20000);
  req.on("close",()=>clearTimeout(timer));req.on("error",reject);req.end(body);
 });
}
(async()=>{
 const me=await api("getMe",{});
 if(!me.ok||String(me.result.username).toLowerCase()!=="gaybbs_bot"||me.result.id===8086265383)throw Error("BOT_IDENTITY_INVALID");
 const allowed=new Set([621,990,991,992,993,994,995,996,997,998,999]);
 if(tasks.length!==11||new Set(tasks.map(t=>t.tid)).size!==11||tasks.some(t=>!allowed.has(t.tid)||!Number.isSafeInteger(t.board)||t.board<=0||!Number.isSafeInteger(t.posting)||t.posting<=0||t.board===t.posting))throw Error("TARGET_INVALID");
 let failures=0;
 for(const t of tasks){
  try{
   const pin=await api("pinChatMessage",{chat_id:chat,message_id:t.board,disable_notification:true});
   if(!pin.ok||pin.result!==true){console.log(JSON.stringify({tid:t.tid,status:"BOARD_PIN_FAILED",code:pin.error_code}));failures++;continue;}
   const unpin=await api("unpinChatMessage",{chat_id:chat,message_id:t.posting});
   const alreadyAbsent=!unpin.ok&&unpin.error_code===400&&/message is not pinned|message to unpin not found/i.test(String(unpin.description||""));
   if(!(unpin.ok&&unpin.result===true)&&!alreadyAbsent){console.log(JSON.stringify({tid:t.tid,status:"POSTING_UNPIN_FAILED",code:unpin.error_code}));failures++;continue;}
   console.log(JSON.stringify({tid:t.tid,board:t.board,posting:t.posting,status:"PASS",unpin:alreadyAbsent?"ALREADY_ABSENT":"CONFIRMED"}));
  }catch{console.log(JSON.stringify({tid:t.tid,status:"TRANSPORT_UNCONFIRMED"}));failures++;}
 }
 if(failures)process.exitCode=1;
})().catch(()=>{console.log(JSON.stringify({status:"PREFLIGHT_FAILED"}));process.exitCode=1;});
"""
source=node.replace("__TASKS__",json.dumps(tasks))
check=subprocess.run(["docker","exec","-i","deploy-gaybbs-1","node","--check","-"],input=source,text=True,capture_output=True,timeout=15)
if check.returncode:raise RuntimeError("NODE_SYNTAX_FAILED")
p=subprocess.run(["docker","exec","-i","deploy-gaybbs-1","node","-"],input=source,text=True,capture_output=True,timeout=200)
result=[json.loads(line) for line in p.stdout.splitlines() if line.startswith("{")]
for row in result:print("AREA_PIN_RESULT="+json.dumps(row),flush=True)
if p.returncode or len(result)!=11 or any(r.get("status")!="PASS" for r in result):raise RuntimeError("PIN_OPERATION_INCOMPLETE")
print("AREA_BOARD_PIN_AND_POSTING_UNPIN=PASS",flush=True)
PY
